// Differential driver: runs every generated argv through the Python executable and
// through the Node port, comparing stdout / stderr / exit code byte-for-byte.
import { spawnSync } from 'node:child_process';

const EXE = '/workspace/dataset/test10_executable';
const JS = process.argv[2] || '/output/test10.mjs';

const cases = JSON.parse(
  spawnSync(process.execPath, ['/tmp/diff/gen_cases.mjs'], { encoding: 'buffer' }).stdout.toString('utf8'),
);

// The PyInstaller crash banner embeds the runtime PID, which can never match.
const normalize = (s) => s.replace(/\[PYI-\d+:ERROR\]/g, '[PYI-PID:ERROR]');

let pass = 0;
const fails = [];
for (const argv of cases) {
  const py = spawnSync(EXE, argv, { encoding: 'buffer', maxBuffer: 1 << 26 });
  const js = spawnSync(process.execPath, [JS, ...argv], { encoding: 'buffer', maxBuffer: 1 << 26 });
  const po = py.stdout.toString('utf8');
  const jo = js.stdout.toString('utf8');
  const pe = normalize(py.stderr.toString('utf8'));
  const je = normalize(js.stderr.toString('utf8'));
  if (po === jo && pe === je && py.status === js.status) {
    pass++;
  } else {
    fails.push({ argv, py: { out: po, err: pe, rc: py.status }, js: { out: jo, err: je, rc: js.status } });
  }
}

console.log(`total=${cases.length} pass=${pass} fail=${fails.length}`);
for (const f of fails.slice(0, 25)) {
  console.log('\n### argv=' + JSON.stringify(f.argv));
  console.log('py rc=' + f.py.rc + ' out=' + JSON.stringify(f.py.out) + ' err=' + JSON.stringify(f.py.err));
  console.log('js rc=' + f.js.rc + ' out=' + JSON.stringify(f.js.out) + ' err=' + JSON.stringify(f.js.err));
}
process.exit(fails.length ? 1 : 0);

